style.css:
/* Apply flex and direction to container */
main > div:first-of-type > div:nth-of-type(2) > div:nth-of-type(2) > div:nth-of-type(2) > div:first-of-type > div:first-of-type > article:first-of-type > div:first-of-type > div:first-of-type {
  display: flex;
  flex-direction: row;
}

/* Apply width: 50% to the explaination */
main > div:first-of-type > div:nth-of-type(2) > div:nth-of-type(2) > div:nth-of-type(2) > div:first-of-type > div:first-of-type > article:first-of-type > div:first-of-type > div:first-of-type > div:first-of-type {
  width: 50%;
}

/* Apply width: 50% and margin-top 0 to the assignment notepad */
main > div:first-of-type > div:nth-of-type(2) > div:nth-of-type(2) > div:nth-of-type(2) > div:first-of-type > div:first-of-type > article:first-of-type > div:first-of-type > div:first-of-type > div:nth-of-type(2) {
  width: 50%;
	margin-top: 0;
}
